import { describe, expect, it } from "vitest"
import { diagnosticSessionHash } from "./diagnosticSessionHash"
import { decodeRunDiagnostic, inspectCanonicalDiagnostic } from "./runDiagnostic"
import { diagnosticFixture, diagnosticFixtureError as error } from "./runDiagnostic.testFixtures"

const sid = "11111111-1111-4111-8111-111111111111"
describe("frozen public diagnostic v2 binding", () => {
  // Golden vectors independently generated by Node crypto; no Node types enter browser code.
  it.each([{"id": "", "expected": "7594d7a049698cff"}, {"id": "11111111-1111-4111-8111-111111111111", "expected": "bf035c2816f8881d"}, {"id": "bamboo-default-supervisor", "expected": "88da72089bf0d1e0"}, {"id": "session-with-utf8-é", "expected": "0eb865bd61c72c1a"}, {"id": "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "expected": "648606b504c10513"}])("matches independent SHA256 for $id", ({id,expected}) => {
    expect(diagnosticSessionHash(id)).toBe(expected)
  })
  it("accepts only the exact bound stop record, with an optional LLM wrapper", () => {
    const d = diagnosticFixture(sid)
    expect(decodeRunDiagnostic(d,sid,error)).toEqual(d)
    expect(decodeRunDiagnostic(d,sid,error.slice(11))).toEqual(d)
    expect(Object.isFrozen(decodeRunDiagnostic(d,sid,error))).toBe(true)
  })
  it.each([
    { schema_version:2 },{ diagnostic_id:"sk-private" },{ request_id:"00000000-0000-4000-8000-000000000000" },
    { error_id:null },{ provider:"private provider" },{ session_hash:null },{ session_hash:"0".repeat(16) },
    { run_id:"private-execution-proof" },{ observed_at:"private timestamp" },{ event:"attempt_start" },
    { phase:"private body" },{ failure:"PRIVATE_BODY" },{ upstream_outcome:"sent" },{ attempt:5 },{ attempt:-1 },
    { attempt_limit:0 },{ attempt_limit:5 },{ total_budget_ms:60001 },{ remaining_budget_ms:60001 },
    { attempt_timeout_ms:60001 },{ status:999 },{ retry_delay_ms:-1 },{ stop_reason:null },
    { stop_reason:"private reason" },{ total_elapsed_ms:Number.MAX_SAFE_INTEGER+1 },{ api_key:"PRIVATE_CANARY" },
  ])("rejects unknown/malformed/free-text projection %j", (patch) => {
    expect(decodeRunDiagnostic({ ...diagnosticFixture(sid), ...patch },sid,error)).toBeNull()
  })
  it("rejects foreign session, copied marker substrings, full-error changes and oversized inputs", () => {
    const d = diagnosticFixture(sid)
    expect(decodeRunDiagnostic(d,"other-session",error)).toBeNull()
    expect(decodeRunDiagnostic(d,sid,"arbitrary body: "+error)).toBeNull()
    expect(decodeRunDiagnostic(d,sid,error.replace("limit 4","limit 3"))).toBeNull()
    expect(decodeRunDiagnostic({ ...d, failure:"x".repeat(5000) },sid,error)).toBeNull()
    expect(decodeRunDiagnostic({ ...d, session_hash:null },"x".repeat(1025),error)).toBeNull()
  })
  it("reads one exact canonical receipt and withdraws old fields after missing/changed/new-run reads", () => {
    const canonical = { id:sid,is_running:false,last_run_status:"error",last_run_error:error,last_run_diagnostic:diagnosticFixture(sid) }
    expect(inspectCanonicalDiagnostic(canonical,sid,error).status).toBe("confirmed")
    for (const changed of [{ id:"foreign" },{ is_running:true },{ last_run_status:"completed" },{ last_run_error:"another error" }]) {
      expect(inspectCanonicalDiagnostic({ ...canonical,...changed },sid,error)).toEqual({ status:"changed",diagnostic:null })
    }
    for (const missing of [undefined,null,{ ...diagnosticFixture(sid), raw_body:"PRIVATE" }]) {
      expect(inspectCanonicalDiagnostic({ ...canonical,last_run_diagnostic:missing },sid,error)).toEqual({ status:"not_provided",diagnostic:null })
    }
  })
})
